import{_ as o,C as d,o as t,c,a2 as s,E as i,j as e,a as l}from"./chunks/framework.CeYlivdO.js";const b=JSON.parse('{"title":"std::array vs 一般数组","description":"对比std::array与传统数组","frontmatter":{"chapter":5,"cpp_standard":[11,14,17,20],"description":"对比std::array与传统数组","difficulty":"intermediate","order":6,"platform":"stm32f1","prerequisites":["Chapter 3: 内存与对象管理"],"reading_time_minutes":5,"tags":["cpp-modern","intermediate","stm32f1"],"title":"std::array vs 一般数组"},"headers":[],"relativePath":"vol8-domains/embedded/06-array-vs-raw-arrays.md","filePath":"vol8-domains/embedded/06-array-vs-raw-arrays.md","lastUpdated":null}'),n={name:"vol8-domains/embedded/06-array-vs-raw-arrays.md"};function p(m,a,y,h,u,q){const r=d("OnlineCompilerDemo");return t(),c("div",null,[a[0]||(a[0]=s('<h1 id="嵌入式c-教程——std-array-vs-c-数组-你们知道嘛" tabindex="-1">嵌入式C++教程——<code>std::array</code> vs C 数组，你们知道嘛？ <a class="header-anchor" href="#嵌入式c-教程——std-array-vs-c-数组-你们知道嘛" aria-label="Permalink to &quot;嵌入式C++教程——`std::array` vs C 数组，你们知道嘛？&quot;">​</a></h1><p>写嵌入式代码时，你大概率会在两种写法间犹豫：<code>int buf[16];</code> 和 <code>std::array&lt;int, 16&gt; buf;</code>。如果你像我（或者像你之前的文章风格那样）既爱性能又爱优雅，你会想知道：哪种更&quot;嵌入式友好&quot;？</p><hr><h2 id="为什么-std-array-看上去像-c-数组穿了件外套-——但其实更聪明" tabindex="-1">为什么 <code>std::array</code> 看上去像&quot;C 数组穿了件外套&quot;——但其实更聪明 <a class="header-anchor" href="#为什么-std-array-看上去像-c-数组穿了件外套-——但其实更聪明" aria-label="Permalink to &quot;为什么 `std::array` 看上去像&quot;C 数组穿了件外套&quot;——但其实更聪明&quot;">​</a></h2><p>从表面看，<code>std::array&lt;T, N&gt;</code> 底层就是包含一个 <code>T elems[N]</code> 的聚合类型：内存上元素是连续的，元素布局没有神秘的开销。所以在很多场景下，<code>std::array</code> 与裸数组的性能、内存占用是等价的。换句话说，你不会因为换成 <code>std::array</code> 而在运行时付出额外费用。</p><p>但 <code>std::array</code> 把数组包进了一个类型：它有值语义（可以拷贝、赋值）、有 <code>.size()</code>、有 <code>.data()</code>、有 <code>begin()</code>/<code>end()</code>、能和 STL 算法无缝对接、支持 <code>constexpr</code>（在现代编译器下），还能作为模板参数被更好地推断。最关键的是，它把&quot;长度是类型的一部分&quot;这一信息显式化，调用接口时更不容易丢失长度信息。</p><p>换句话说：<code>std::array</code> 是&quot;更安全、更现代&quot;的数组。</p><hr><h2 id="裸-c-数组的老实巴交与致命天真" tabindex="-1">裸 C 数组的老实巴交与致命天真 <a class="header-anchor" href="#裸-c-数组的老实巴交与致命天真" aria-label="Permalink to &quot;裸 C 数组的老实巴交与致命天真&quot;">​</a></h2><p>裸数组的优点是&quot;零抽象&quot;，也就是你对内存完全可控：这在启动代码、驱动层、位于特定地址空间的缓冲区（比如映射到某个外设寄存器地址）非常重要。裸数组在 ABI、链接器、对齐方面不给你出难题——只要你知道自己在做什么，它非常可靠。</p><p>但裸数组也带来一堆常见的踩坑：它会在函数参数中退化为指针（因此 <code>sizeof</code> 在函数里会给出指针大小），不能直接拷贝赋值（<code>b = a;</code> 会编译不过），也没有任何边界或尺寸信息保护。嵌入式代码里，这些&quot;方便的缺失&quot;会让你经常写 <code>memcpy</code>、频繁查 <code>N</code> 是否写对、在审查时犯&quot;忘记传长度&quot;的低级错误。</p><p>一个真实场景：你把裸数组传给 C API 做 DMA，忘了告诉调用方长度，结果 DMA 越界写到你最珍贵的变量上。裸数组没有提醒你这类低概率高代价错误。</p><hr><h2 id="std-array-的优点-更安全、更可读、和现代-c-更友好" tabindex="-1"><code>std::array</code> 的优点：更安全、更可读、和现代 C++ 更友好 <a class="header-anchor" href="#std-array-的优点-更安全、更可读、和现代-c-更友好" aria-label="Permalink to &quot;`std::array` 的优点：更安全、更可读、和现代 C++ 更友好&quot;">​</a></h2><p><code>std::array</code> 的日常优势可以总结为：语义清晰、接口友好、可与算法直接配合。例如，<code>std::sort(a.begin(), a.end())</code> 或 <code>std::span(a)</code> 都是顺手可得的好处。<code>std::array</code> 可以 <code>=</code>, 复制，甚至作为函数返回值安全返回（不会退化），这在很多中层逻辑里能让代码更简洁、更少内存操作 bug。</p><p>在嵌入式上下文，这意味着测试代码、单元测试桩、缓冲区封装这些地方会更干净：你可以写成返回 <code>std::array</code> 的函数而不是整堆 <code>memcpy</code>。而且当编译器支持 <code>constexpr</code> 时，<code>std::array</code> 能在编译期构造常量表，代码既高效又安全。</p><hr><h2 id="那么什么时候应该继续用裸-c-数组" tabindex="-1">那么什么时候应该继续用裸 C 数组？ <a class="header-anchor" href="#那么什么时候应该继续用裸-c-数组" aria-label="Permalink to &quot;那么什么时候应该继续用裸 C 数组？&quot;">​</a></h2><p><code>std::array</code> 很好，但并不是无敌。在下面几类场景，裸数组仍然是更合适的选择：</p><ol><li><strong>初始化阶段或早期引导代码（startup / crt0）</strong>：在 <code>main()</code> 之前，C++ 的全局构造规则和运行时支持可能会麻烦。裸数组在这类代码里更直白、更可靠，尤其是当你需要绝对确保没有任何构造器或运行时代码介入时。</li><li><strong>放在特定链接段 / 放到固定地址</strong>：像中断向量表、设备映射缓冲区、bootloader 的表格等，往往需要在链接脚本里精确声明对象位置和字节序。裸数组更直接映射到期望的内存布局，减少不必要的抽象。</li><li><strong>严格的 ABI 或与外部 C API 的互操作，且你需要写裸指针</strong>：虽然 <code>std::array</code> 有 <code>.data()</code>，但在一些非常讲究二进制兼容性的场景中，审计时用裸数组更直观（尤其是老代码基）。</li><li><strong>极端资源受限且要避免编译器生成任何额外元信息</strong>：这类情况稀有，但存在于某些超嵌入式或者内核最底层代码中。</li></ol><hr><h2 id="所以怎么说" tabindex="-1">所以怎么说？ <a class="header-anchor" href="#所以怎么说" aria-label="Permalink to &quot;所以怎么说？&quot;">​</a></h2><p>裸数组是简洁、可靠的工具，适合最接近硬件的那一层；<code>std::array</code> 是更现代、更安全、更贴合 C++ 思想的容器，适合业务逻辑、算法层以及绝大多数嵌入式应用代码。把二者当作工具箱里的两把刀：修理芯片引脚用军刀（裸数组），写协议解析和缓冲逻辑用精密小刀（<code>std::array</code>）。</p><p>最后一句鸡汤式建议：当你能把数组尺寸写成 <code>std::array&lt;T, N&gt;</code> 的模板参数时，就写成 <code>std::array</code>；当你必须在链接脚本或最早期的引导代码里精确控制每个字节时，回到裸数组，别害羞。嵌入式开发不是为了&quot;保持纯粹&quot;，而是为了按实际需要用对工具——<code>std::array</code> 很多时候会让你代码更少、错误更少，偶尔你还是得把手伸进裸内存去修一修底层。</p><hr><h2 id="在线运行" tabindex="-1">在线运行 <a class="header-anchor" href="#在线运行" aria-label="Permalink to &quot;在线运行&quot;">​</a></h2><p>在线运行 std::array vs C 数组的对比示例，验证零开销抽象：</p>',27)),i(r,{title:"std::array 与 C 数组：零开销对比","source-path":"code/examples/compiler_explorer/array_vs_carray_host.cpp","arm-source-path":"code/examples/compiler_explorer/array_vs_carray_arm.cpp",description:"在线运行并验证 std::array 与 C 数组的 sizeof 一致性，以及指针退化问题。","allow-run":"","allow-x86-asm":"","allow-arm-asm":""}),a[1]||(a[1]=e("h2",{id:"代码示例",tabindex:"-1"},[l("代码示例 "),e("a",{class:"header-anchor",href:"#代码示例","aria-label":'Permalink to "代码示例"'},"​")],-1))])}const C=o(n,[["render",p]]);export{b as __pageData,C as default};
